## DuckDB Example

```sql
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET s3_endpoint='s3-west.nrp-nautilus.io';
SET s3_url_style='path';
SET s3_use_ssl=false;

-- Segments by study type and eligibility
SELECT Study_Type, In_Eligibl, COUNT(*) AS n
FROM read_parquet('s3://public-rivers/american-rivers/nri-2024.parquet')
GROUP BY Study_Type, In_Eligibl ORDER BY n DESC;

-- Segments added since 2016 (in NRI-2024 but not NRI-2016 by count)
-- Note: compare NRI datasets to identify new segments
SELECT State1, COUNT(*) AS n
FROM read_parquet('s3://public-rivers/american-rivers/nri-2024.parquet')
GROUP BY State1 ORDER BY n DESC LIMIT 15;
```

